mkdir -p src/act && cat > src/act/pr-body.ts <<'EOF'
export interface PrBodyTask {
  id: string;
  incumbentPass: boolean;
  candidatePass: boolean;
  costUsd: number | null;
  traceUrl?: string;
  entireUrl?: string;
}

export interface PrBodyInput {
  repo: string;
  incumbent: string;
  promoted: string;
  tasks: PrBodyTask[];
  rejected: { candidate: string; reasons: string[] }[];
  evidenceLevel: 'B' | 'C';
}

const mark = (pass: boolean): string => (pass ? '✓' : '✗');

const cell = (text: string): string => text.replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');

const cost = (usd: number | null): string =>
  usd === null || !Number.isFinite(usd) ? 'n/a' : usd.toFixed(2);

export function renderPrBody(input: PrBodyInput): string {
  const { repo, incumbent, promoted, tasks, rejected, evidenceLevel } = input;
  const n = tasks.length;
  const candidatePasses = tasks.filter((t) => t.candidatePass).length;
  const incumbentPasses = tasks.filter((t) => t.incumbentPass).length;

  const lines: string[] = [];

  lines.push('## Summary', '');
  lines.push(`Roster promotes setup \`${promoted}\` over incumbent \`${incumbent}\` in \`${repo}\`.`, '');
  lines.push(`Evidence level: ${evidenceLevel}`, '');
  lines.push(`${candidatePasses} of ${n} tasks passed (incumbent ${incumbentPasses} of ${n})`, '');

  lines.push('## Evidence', '');
  lines.push('| Task | Incumbent | Promoted | Cost (USD) |');
  lines.push('| --- | --- | --- | --- |');
  for (const t of tasks) {
    lines.push(`| ${cell(t.id)} | ${mark(t.incumbentPass)} | ${mark(t.candidatePass)} | ${cost(t.costUsd)} |`);
  }
  lines.push('');

  lines.push('## Rejected candidates', '');
  if (rejected.length === 0) {
    lines.push('None');
  } else {
    for (const r of rejected) {
      lines.push(`- \`${r.candidate}\``);
      if (r.reasons.length === 0) {
        lines.push('  - No reason recorded');
      } else {
        for (const reason of r.reasons) lines.push(`  - ${reason.replace(/\r?\n/g, ' ')}`);
      }
    }
  }
  lines.push('');

  lines.push('## Links', '');
  const links: string[] = [];
  for (const t of tasks) {
    if (t.traceUrl) links.push(`- ${t.id}: [trace](${t.traceUrl})`);
    if (t.entireUrl) links.push(`- ${t.id}: [entire](${t.entireUrl})`);
  }
  if (links.length === 0) lines.push('None');
  else lines.push(...links);
  lines.push('');

  return lines.join('\n');
}
EOF
cat > tests/pr-body.test.ts <<'EOF'
import { describe, expect, test } from 'bun:test';
import { renderPrBody } from '../src/act/pr-body';

const base = {
  repo: 'acme/app',
  incumbent: 'A',
  promoted: 'C',
  evidenceLevel: 'B' as const,
  tasks: [
    { id: 't1', incumbentPass: false, candidatePass: true, costUsd: 0.5, traceUrl: 'https://trace/1', entireUrl: 'https://entire/1' },
    { id: 't2', incumbentPass: true, candidatePass: true, costUsd: null },
    { id: 't3', incumbentPass: false, candidatePass: false, costUsd: 1.234 },
  ],
  rejected: [{ candidate: 'D', reasons: ['regressed t2', 'cost'] }],
};

describe('renderPrBody', () => {
  const out = renderPrBody(base);

  test('has all sections in order', () => {
    const idx = ['## Summary', '## Evidence', '## Rejected candidates', '## Links'].map((s) => out.indexOf(s));
    expect(idx.every((i) => i >= 0)).toBe(true);
    expect([...idx].sort((a, b) => a - b)).toEqual(idx);
  });

  test('totals line', () => {
    expect(out).toContain('2 of 3 tasks passed (incumbent 1 of 3)');
  });

  test('table rows with marks and cost formatting', () => {
    expect(out).toContain('| t1 | ✗ | ✓ | 0.50 |');
    expect(out).toContain('| t2 | ✓ | ✓ | n/a |');
    expect(out).toContain('| t3 | ✗ | ✗ | 1.23 |');
  });

  test('rejected reasons and links listed', () => {
    expect(out).toContain('- `D`');
    expect(out).toContain('  - regressed t2');
    expect(out).toContain('[trace](https://trace/1)');
    expect(out).toContain('[entire](https://entire/1)');
  });

  test('empty rejected says None', () => {
    const r = renderPrBody({ ...base, rejected: [] });
    expect(r).toMatch(/## Rejected candidates\n\nNone/);
  });

  test('no links says None; zero tasks', () => {
    const r = renderPrBody({ ...base, tasks: [], rejected: [] });
    expect(r).toMatch(/## Links\n\nNone/);
    expect(r).toContain('0 of 0 tasks passed (incumbent 0 of 0)');
  });

  test('no banned adjectives', () => {
    expect(out).not.toMatch(/significant|best/i);
  });

  test('escapes pipes in task ids', () => {
    const r = renderPrBody({ ...base, tasks: [{ id: 'a|b', incumbentPass: true, candidatePass: true, costUsd: 0 }] });
    expect(r).toContain('| a\\|b | ✓ | ✓ | 0.00 |');
  });
});
EOF
